from collections import deque

def bfs_shortest_path(graph, start, goal):
    if start == goal:
        return 0
    visited = {start}
    q = deque([(start, 0)])
    while q:
        node, d = q.popleft()
        for nei in graph.get(node, []):
            if nei == goal:
                return d + 1
            if nei not in visited:
                visited.add(nei)
                q.append((nei, d + 1))
    return -1
```

